## Sample Code Snippet: OAuth 2.0 + Scope Check in Node.js

```js
// Express middleware
const { verify } = require('jsonwebtoken');
const jwksClient = require('jwks-rsa');

const client = jwksClient({
  jwksUri: `https://{YOUR_OIDC_DOMAIN}/.well-known/jwks.json`
});

function getKey(header, callback) {
  client.getSigningKey(header.kid, function(err, key) {
    const signingKey = key.publicKey || key.rsaPublicKey;
    callback(null, signingKey);
  });
}

function authMiddleware(requiredScope) {
  return function(req, res, next) {
    const authHeader = req.headers.authorization;
    if (!authHeader) return res.sendStatus(401);

    const token = authHeader.split(' ')[1];
    verify(token, getKey, { algorithms: ['RS256'] }, (err, decoded) => {
      if (err) return res.sendStatus(401);
      if (!decoded.scope?.includes(requiredScope)) return res.sendStatus(403);
      req.user = decoded;
      next();
    });
  };
}

// Usage
app.get('/admin', authMiddleware('admin:read'), (req, res) => {
  res.json({ secret: 'admin data' });
});
```

*Key points* – use a JWKS endpoint, validate `aud`, `iss`, `exp`, and enforce `scope`.  

